entries[59628] = { ["name"] = "Schurkenhandel", ["text"] = "Sofort\nDas gewählte Gruppen- oder Schlachtzugsmitglied wird das Ziel Eures Schurkenhandels. Die von Eurem nächsten Angriff erzeugte Bedrohung sowie aller innerhalb von 6 Sek. danach erfolgenden Aktionen wird auf das Ziel übertragen. Zusätzlich wird jeglicher verursachte Schaden des Ziels in dieser Zeit um 15% erhöht." }
