entries[59636] = { ["name"] = "Ring - Ausdauer", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Eterniumrute\nReagenzien:\nSchleierstaub (8), Große kosmische Essenz\nEuren eigenen Ring dauerhaft verzaubern, sodass die Ausdauer um 30 erhöht wird. Dadurch wird der Ring seelengebunden." }
