entries[59672] = { ["name"] = "Metamorphose", ["text"] = "Sofort\nIhr verwandelt Euch 30 Sek. lang in einen Dämon. Diese Gestalt erhöht Eure Rüstung um 600%, Euren Schaden um 20% und die Chance, einen kritischen Nahkampftreffer zu erleiden, wird um 6% verringert. Die Dauer auf Euch wirkender Betäubungs- und Verlangsamungseffekte wird um 50% verringert. Zusätzlich zu Euren Fähigkeiten gewinnt Ihr einige einzigartige Dämonenfähigkeiten. 3 Minuten Abklingzeit." }
