entries[60013] = { ["name"] = "Erdschild", ["text"] = "40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf. 6 Aufladungen. Hält 2 Min. lang an.\n(3.5s Abklingzeit)" }
