entries[60017] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht 637 to 713 Schaden. Zusätzlich werden die nächsten erfolgreichen 3 Nahkampfangriffe 1,5% der maximalen Gesundheit wiederherstellen. Dieser Effekt hält 8 Sek. lang an. Schaden basiert auf Angriffskraft." }
