entries[60019] = { ["name"] = "Donnerknall", ["text"] = "Sofort 6 sek. Abklingzeit\nTrifft nahe Feinde, erhöht die Zeit zwischen ihren Angriffen 30 Sek. lang um 20% und verursacht 900 Schaden. Schaden wird durch Angriffskraft erhöht. Diese Fähigkeit verursacht zusätzliche Bedrohung und wirkt auf maximal 4 Ziele." }
entries[60020] = { ["name"] = "Eiswolke", ["text"] = "Sofort\nVerursacht sofort 5000 Frostschaden und danach pro Sek. 2500 Frostschaden. Hält 10 Sek. lang an." }
